\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage{helvet} % Sans-serif
\renewcommand{\familydefault}{\sfdefault}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usepackage{booktabs}
\pagestyle{empty}

% ── Bloomberg Terminal Color Theme ──
\definecolor{primary}{HTML}{0A192F}      % Deep navy (Title background, accent stripes)
\definecolor{secondary}{HTML}{112240}    % Lighter navy
\definecolor{accent}{HTML}{64FFDA}       % Electric Cyan
\definecolor{greenup}{HTML}{00FF00}      % Bright Green for growth
\definecolor{bgposter}{HTML}{020C1B}     % Poster background (almost black navy)
\definecolor{cardbg}{HTML}{0A192F}       % Card background
\definecolor{cardtitlebg}{HTML}{112240}  % Card title bar background
\definecolor{textwhite}{HTML}{CCD6F6}    % Primary text
\definecolor{textgray}{HTML}{8892B0}     % Secondary text
\definecolor{stathighlight}{HTML}{112240} % Stat box

\pagecolor{bgposter}
\color{textwhite}

\setlist[itemize]{leftmargin=36pt, itemsep=16pt, parsep=6pt, topsep=6pt, label={\color{accent}$\blacktriangleright$}}

\newcommand{\up}{{\color{greenup}$\uparrow$}}

% Card Styles
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={8pt}{0pt}{accent},
    left=32pt, right=32pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=16pt, bottomtitle=16pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  tablecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={8pt}{0pt}{greenup},
    left=32pt, right=32pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{greenup},
    coltitle=greenup, colbacktitle=cardtitlebg,
    toptitle=16pt, bottomtitle=16pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  }
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=12mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5, color=black}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{84}{100}\selectfont\bfseries Open Source Contributor Index}\\[24pt]
  {\fontsize{56}{66}\selectfont\bfseries\color{accent} March 2026 Rankings}\\[16pt]
  {\fontsize{34}{42}\selectfont\color{textgray} A data-driven ranking of the world's top commercial organizations by their employees' open source contributions on GitHub.}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=24pt, right=24pt, top=12pt, bottom=12pt,
  valign=center, borderline south={4pt}{0pt}{accent},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{textwhite} 239}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{accent} Organizations Tracked}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{greenup}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{greenup} 2,721}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{accent} Top 10 Active Contributors}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{textwhite} 1,986}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{accent} \#1 Total Community (Google)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{textwhite} Python}\\[8pt]
      {\fontsize{30}{36}\selectfont\color{accent} Top Language (20.3\%)}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ LEADERBOARD (Centerpiece) ══
\posterbox[tablecard, title={Top 10 Contributing Organizations}
]{name=leaderboard, column=1, span=2, between=row5 and row15}{
  \fontsize{34}{44}\selectfont
  \vspace{24pt}
  \renewcommand{\arraystretch}{2.0}
  \centering
  \begin{tabular}{c l r l r l}
  \rowcolor{cardtitlebg}
  \color{textgray}\bfseries Rank & \color{textgray}\bfseries Organization & \color{textgray}\bfseries Active & \color{textgray}\bfseries MoM & \color{textgray}\bfseries Community & \color{textgray}\bfseries MoM \\
  1 & \bfseries Google & 548 & \up +128 & 1,986 & \up +267 \\
  \rowcolor{stathighlight}
  2 & Microsoft & 438 & \up +74 & 1,189 & \up +174 \\
  3 & Red Hat & 432 & \up +94 & 1,378 & \up +193 \\
  \rowcolor{stathighlight}
  4 & AMD & 233 & \up +66 & 627 & \up +109 \\
  5 & Datadog & 221 & \up +34 & 411 & \up +58 \\
  \rowcolor{stathighlight}
  6 & Intel & 217 & \up +48 & 707 & \up +82 \\
  7 & NVIDIA & 194 & \up +41 & 650 & \up +106 \\
  \rowcolor{stathighlight}
  8 & SUSE & 158 & \up +32 & 353 & \up +51 \\
  9 & IBM & 140 & \up +44 & 616 & \up +133 \\
  \rowcolor{stathighlight}
  10 & SAP & 140 & \up +34 & 378 & \up +54 \\
  \end{tabular}

  \vspace{36pt}
  \begin{itemize}
    \item \textbf{Google holds the top position} with 548 active contributors, adding 128 new contributors this month.
    \item \textbf{AMD climbed two spots} to rank 4th, reflecting significant MoM growth.
    \item \textbf{Red Hat maintains a massive total community}, closely trailing Microsoft in active contributors.
  \end{itemize}
}

% ══ GROWTH MOMENTUM ══
\posterbox[darkcard, title={Monthly Growth Momentum}
]{name=growth, column=3, between=row5 and row10}{
  \fontsize{34}{44}\selectfont
  \vspace{12pt}
  Every organization in the top 10 showed \textbf{\color{greenup}positive month-over-month growth} in both active contributors and total community.
  \vspace{24pt}

  \begin{center}
    \fcolorbox{greenup}{cardbg}{\parbox{0.9\linewidth}{
      \centering\vspace{16pt}
      {\fontsize{80}{90}\selectfont\bfseries\color{greenup} +595}\\[12pt]
      {\fontsize{30}{36}\selectfont\color{textwhite} Combined Active Contributors MoM}\vspace{16pt}
    }}
  \end{center}

  \vspace{24pt}
  \begin{itemize}
    \item \textbf{IBM showed strong relative growth}, adding 44 active contributors (a roughly 46\% increase).
    \item The total community across the top 10 expanded by \textbf{1,227 members} in a single month.
  \end{itemize}
}

% ══ TOP LANGUAGES ══
\posterbox[darkcard, title={Top Programming Languages}
]{name=languages, column=3, between=row10 and row16}{
  \fontsize{34}{44}\selectfont
  \vspace{12pt}
  Python leads decisively, reflecting its dominance in AI/ML and cloud-native tooling.
  \vspace{24pt}

  \renewcommand{\arraystretch}{1.8}
  \centering
  \begin{tabular}{l l l}
  \rowcolor{cardtitlebg}
  \color{textgray}\bfseries Language & \color{textgray}\bfseries Share & \color{textgray}\bfseries Focus Area \\
  \bfseries\color{accent} Python & \bfseries\color{accent} 20.3\% & AI/ML, Cloud \\
  \rowcolor{stathighlight}
  C++ & 14.3\% & Systems, Core \\
  Go & 11.6\% & Infrastructure \\
  \rowcolor{stathighlight}
  C & 10.9\% & Kernel, Devices \\
  TypeScript & 10.5\% & Web, Tooling \\
  \rowcolor{stathighlight}
  Java & 4.4\% & Enterprise \\
  \end{tabular}

  \vspace{36pt}
  \begin{itemize}
    \item \textbf{Systems-level languages} (C++ and C) together account for over \textbf{25\%} of contributions.
    \item \textbf{Infrastructure \& Cloud} represented by Go's strong presence.
  \end{itemize}
}

% ══ ECOSYSTEM SCALE & LICENSING ══
\posterbox[darkcard, title={Ecosystem Scale \& Licensing}
]{name=ecosystem, column=1, span=2, between=row15 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{12pt}

  \begin{minipage}[t]{0.48\linewidth}
    \textbf{\color{accent}The Licensing Landscape}
    \vspace{16pt}
    \begin{itemize}
      \item \textbf{Apache-2.0} is the most prevalent license, enabling broad commercial adoption.
      \item \textbf{MIT} follows as the second most popular permissive license.
      \item \textbf{GPL-2.0} remains dominant in copyleft usage.
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.48\linewidth}
    \textbf{\color{accent}Why It Matters}
    \vspace{16pt}
    \begin{itemize}
      \item \textbf{Transparent Benchmark:} OSCI tracks 239 commercial organizations worldwide.
      \item \textbf{Open Data:} The index itself is open source (GPL v3.0), ensuring transparent criteria.
      \item \textbf{Value Generation:} Base data helps measure the economic value of open source.
    \end{itemize}
  \end{minipage}
}

% ══ CONCLUSION FILLER ══
\posterbox[darkcard, title={Key Takeaway}
]{name=takeaway, column=3, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{24pt}
  \begin{center}
    \textbf{\color{accent}Corporate open source engagement is accelerating.}
    \vspace{24pt}

    The concentration of growth among the top 10 providers indicates that major commercial entities are aggressively expanding their open source footprints, particularly in AI and cloud-native ecosystems driven by Python and C++.
  \end{center}
}

\end{tcbposter}
\end{document}
EOF
